/// `build_runner` adapter for the `l10n_plus` code generator.
///
/// The CLI remains the primary workflow; this exists for projects that already
/// run `build_runner` and want translations regenerated by the same command.
library;

import 'package:build/build.dart';

import 'src/builder.dart';

export 'src/builder.dart' show L10nPlusBuilder;

/// Builder factory referenced from `build.yaml`.
Builder l10nPlusBuilder(BuilderOptions options) => L10nPlusBuilder(options);
